html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro lines(value, blank=3) -%}
{%- if value %}<p class="answer">{{ v(value) | replace("\n", "<br>") }}</p>{% else %}{% for i in range(blank) %}<p class="dots"></p>{% endfor %}{% endif -%}
{%- endmacro -%}
{%- macro person(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set employee = frappe.get_doc("Employee", doc.employee) -%}
{%- macro addressee(on) -%}
	{%- if logo %}<p class="logo"><img src="{{ logo }}" style="max-height: 52px"></p>{% endif %}
	<p class="addr">{{ day(on) }}</p>
	<p class="addr" style="margin-top: 12px">{{ v(employee.salutation) }} {{ v(employee.employee_name) }}</p>
	<p class="addr">{{ v(employee.employee_number or employee.name) }}</p>
	<p class="addr">Division &ndash; {{ v(employee.department) }}</p>
	<p class="addr" style="margin-bottom: 14px">Plant, {{ v(employee.branch) }}</p>
	<p><strong>Dear {{ v(employee.first_name) }},</strong></p>
{%- endmacro -%}
{%- macro signatory(setting, title) -%}
	{%- set signer = frappe.db.get_single_value("Onboarding Settings", setting) -%}
	<p style="margin-top: 26px">&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</p>
	<p class="addr">{{ v((frappe.db.get_value("Employee", signer, "employee_name") if signer else "") | upper) }}</p>
	<p class="addr">{{ v(title) }}</p>
{%- endmacro -%}
<style>
	.lpl-letter { font-family: Cambria, Georgia, serif; font-size: 12.5px; color: #000; line-height: 1.55; }
	.lpl-letter p { margin: 0 0 12px; }
	.lpl-letter .addr { font-weight: bold; margin: 0; }
	.lpl-letter h4 { font-size: 12.5px; font-weight: bold; text-decoration: underline; margin: 14px 0 12px; }
	.lpl-letter .logo { text-align: right; margin: 0 0 18px; }
	.lpl-letter table.sign { width: 100%; margin: 6px 0 0; }
	.lpl-letter table.sign td { border: none; padding: 8px 0 0; }
</style>
{%- set previous = frappe.db.get_value("Employee Contract", doc.renewal_of, ["start_date", "end_date"], as_dict=True) if doc.renewal_of else none -%}
<div class="lpl-letter">
{%- if not previous %}
	<p><em>The Contract Renewal letter is for a contract that renews another (Renew on the contract ending); this one renews none.</em></p>
{%- else %}
	{{ addressee(doc.creation) }}
	<h4>RE: CONTRACT RENEWAL</h4>
	<p>In reference to your contract letter dated <strong>{{ day(employee.date_of_joining) }}</strong>, I wish to inform you that your contract will expire on <strong>{{ day(previous.end_date) }}</strong>.</p>
	<p>However, due to your satisfactory performance and the recent performance appraisal exercise, I am pleased to inform you that management has considered renewing your contract for {{ "one year" if doc.months == 12 else (v(doc.months) ~ " months") }} effective from <strong>{{ day(doc.start_date) }}</strong> to <strong>{{ day(doc.end_date) }}</strong>.</p>
	<p><strong>Your other terms and conditions of work remain the same.</strong></p>
	<p><strong>Yours Faithfully,</strong></p>
	{{ signatory("executive_director", "EXECUTIVE DIRECTOR") }}
	<p style="margin-top: 18px">I {{ v(employee.employee_name) }} have read and understood the terms and conditions in this letter and agree to it.</p>
	<table class="sign">
		<tr><td>Sign: &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</td><td>Date: &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</td><td></td></tr>
		<tr><td><strong>Witness, HRM &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;</strong></td><td><strong>Sign&hellip;&hellip;&hellip;&hellip;&hellip;</strong></td><td><strong>Date&hellip;&hellip;&hellip;&hellip;&hellip;</strong></td></tr>
		<tr><td><strong>Witness Legal Manager&hellip;&hellip;&hellip;&hellip;</strong></td><td><strong>Sign&hellip;&hellip;&hellip;&hellip;&hellip;</strong></td><td><strong>Date&hellip;&hellip;&hellip;&hellip;&hellip;</strong></td></tr>
	</table>
{%- endif %}
</div>
